  "enrollment": 12,
  "interventions": [
    {
      "description": "Recombinant von Willebrand Factor is a drug that is currently FDA approved to treat patients with certain types of von Willebrand Disease. In the current trial it will be used to treat ECMO patients who have acquired von Willebrand syndrome.",
      "id": 1,
      "name": "Recombinant von Willebrand Factor",
