  ],
  "nct_id": "NCT06118372",
  "phase": "PHASE1",
  "source": "ClinicalTrials.gov",
  "sponsor": "University of Virginia",
  "start_date": "2024-10-03",
  "status": "RECRUITING",
  "study_type": "INTERVENTIONAL",
  "summary": "Adult patients on extracoporeal membrane oxygenation (ECMO) frequently experience bleeding, which is in part caused by acquired von Willebrand syndrome (vWS). Prior in vitro studies have shown that the addition of recombinant von Willebrand Factor (vWF) to ECMO patient blood samples, normalizes platelet adhesion and thrombus formation. This study is a phase I study, where adult ECMO patients with refractory bleeding will be treated with recombinant vWF a single time. The primary objectives are to evaluate the safety, tolerability, and pharmacokinetics of recombinant vWF in adult ECMO patients.",
  "title": "Recombinant vWF Concentrate and ECMO"
}

