  "nct_id": "NCT04308330",
  "phase": "PHASE1",
  "source": "ClinicalTrials.gov",
  "sponsor": "New York Medical College",
  "start_date": "2017-03-17",
  "status": "RECRUITING",
  "study_type": "INTERVENTIONAL",
  "summary": "Investigators are testing new experimental drug combinations such as the combination of vorinostat, vincristine, irinotecan, and temozolomide in the hopes of finding a drug that may be effective against tumors that have come back or that have not responded to standard therapy.\n\nThe goals of this study are:\n\n* To find the highest safe dose of vorinostat that can be given together with vincristine, irinotecan, and temozolomide without causing severe side effects;\n* To learn what kind of side effects this four drug combination can cause;\n* To learn about the effects of vorinostat and the combination of vorinostat, vincristine, irinotecan, and temozolomide on specific molecules in tumor cells;\n* To determine whether the combination of vorinosat, vincristine, irinotecan, and temozolomide is a beneficial treatment.",
  "title": "Vorinostat in Combination With Chemotherapy in Relapsed/Refractory Solid Tumors and CNS Malignancies"
}

